package com.dealhunter.app;
import android.app.*;import android.content.*;import androidx.work.*;import org.json.*;import java.net.*;import java.util.*;import java.util.regex.*;import javax.xml.parsers.*;import org.w3c.dom.*;
public class DealWorker extends Worker {
 public DealWorker(Context c,WorkerParameters p){super(c,p);}
 public Result doWork(){return scan(getApplicationContext())?Result.success():Result.retry();}
 static synchronized boolean scan(Context c){android.content.SharedPreferences p=c.getSharedPreferences("deals",0);String[] names={"Slickdeals Frontpage","Slickdeals Popular","Slickdeals Hot Deals","DealNews Latest","DealNews Popular"}, urls={"https://slickdeals.net/rss.php","https://slickdeals.net/newsearch.php?mode=popdeals&searcharea=deals&searchin=first&rss=1","https://slickdeals.net/newsearch.php?searchin=first&forumchoice%5B%5D=9&rss=1","https://www.dealnews.com/rss/todays-edition","https://content.dealnews.com/dealnews/rss/popular.xml"};ArrayList<JSONObject> deals=new ArrayList<>();HashSet<String> seen=new HashSet<>();int ok=0;for(int i=0;i<urls.length;i++){try{URLConnection conn=new URL(urls[i]).openConnection();conn.setConnectTimeout(15000);conn.setReadTimeout(15000);conn.setRequestProperty("User-Agent","DealHunter/1.0 RSS reader");DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);Document doc;try(java.io.InputStream in=conn.getInputStream()){doc=f.newDocumentBuilder().parse(in);}if(!doc.getDocumentElement().getTagName().equals("rss"))continue;NodeList items=doc.getElementsByTagName("item");for(int j=0;j<items.getLength();j++){Element e=(Element)items.item(j);String title=e.getElementsByTagName("title").item(0).getTextContent(), link=e.getElementsByTagName("link").item(0).getTextContent(), low=title.toLowerCase(Locale.US);NodeList desc=e.getElementsByTagName("description");int discount=ApparelFilter.discount(title,desc.getLength()>0?desc.item(0).getTextContent():"");if(discount<50||!link.startsWith("https://")||!seen.add(title.toLowerCase(Locale.US).replaceAll("\\s+"," ").trim()))continue;JSONObject deal=new JSONObject().put("title",title).put("url",link).put("source",names[i]).put("discount",discount).put("direct",PriceHistory.direct(e)).put("category","Clothing");PriceHistory.record(p,deal);deals.add(deal);}ok++;}catch(Exception e){}}
 deals.sort((a,b)->Integer.compare(b.optInt("discount"),a.optInt("discount")));if(ok==0){p.edit().putString("status","Sources unavailable · showing cached results").apply();return false;}JSONArray a=new JSONArray();for(JSONObject d:deals)a.put(d);p.edit().putString("results",a.toString()).putString("status",ok +"/"+urls.length+" feeds connected · "+deals.size()+" matches").apply();NotificationManager nm=c.getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("deals","Exceptional deals",NotificationManager.IMPORTANCE_HIGH));for(JSONObject d:deals){String key="alert:"+d.optString("url");int n=d.optInt("discount");if(n<p.getInt("alert",70)||n<=p.getInt(key,0))continue;if(android.os.Build.VERSION.SDK_INT>=33&&c.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)continue;PendingIntent pi=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_IMMUTABLE);nm.notify(key.hashCode(),new Notification.Builder(c,"deals").setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle(n+"% advertised discount").setContentText(d.optString("title")).setStyle(new Notification.BigTextStyle().bigText(d.optString("title"))).setContentIntent(pi).setAutoCancel(true).build());p.edit().putInt(key,n).apply();}return true;}
}
